void bfs(Graph G, int src) {
    queue<int> q;
    visited[src] = true;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : G.adj[u])
            if (!visited[v]) {
                visited[v] = true;
                q.push(v);
            }
    }
}

